library(ggplot2)
m<-read.csv('results/prediction_metrics.csv');d<-subset(m,scheme=='LOO')
lev<-c('Mean','A_controls','B_advice','C_five_OLS','D_five_ridge')
lab<-c('Training mean','Controls','Advice + controls','Five layers + controls','Five layers: ridge')
d$model<-factor(d$model,levels=rev(lev),labels=rev(lab))
p<-ggplot(d,aes(RMSE,model))+geom_point(size=3,color='#245b82')+geom_text(aes(label=sprintf('%.3f',RMSE)),nudge_y=.2,size=3.8)+scale_x_continuous(limits=c(10.8,12.35))+labs(title='Prediction of a held-out village',subtitle='Leave-one-village-out cross-validation · 68 villages · lower RMSE is better',x='RMSE (number of calls)',y=NULL,caption='All models and tuning rules were fixed before held-out scores. No confidence intervals are implied.')+theme_minimal(base_size=12)+theme(panel.grid.major.y=element_blank(),panel.grid.minor=element_blank(),plot.title=element_text(face='bold'),plot.caption=element_text(hjust=0))
ggsave('results/prediction_comparison.png',p,width=9,height=4.5,dpi=180)
c<-subset(read.csv('results/model_contrasts.csv'),scheme=='5fold')
z<-rbind(data.frame(repetition=c$repeat_id,difference=c$C_minus_B_RMSE,model='Five-layer OLS'),data.frame(repetition=c$repeat_id,difference=c$D_minus_B_RMSE,model='Five-layer ridge'))
p<-ggplot(z,aes(difference,factor(repetition),color=model))+geom_vline(xintercept=0,linetype='dashed',color='#777777')+geom_point(position=position_dodge(width=.45),size=2.7)+scale_color_manual(values=c('#b35b39','#245b82'))+labs(title='The apparent gain depends on the validation split',subtitle='Ten prespecified repetitions of five-fold cross-validation',x='RMSE difference versus advice + controls (negative favors five layers)',y='Repetition',color=NULL,caption='Five-layer OLS and ridge each beat advice on RMSE in 2 of 10 repetitions. Repetitions are not independent tests.')+theme_minimal(base_size=12)+theme(panel.grid.minor=element_blank(),legend.position='top',plot.title=element_text(face='bold'),plot.caption=element_text(hjust=0))
ggsave('results/partition_sensitivity.png',p,width=9,height=6,dpi=180)
